# Reads result tables only. No CellChat inference, expression cache or Seurat input.
source('mp10_cellchat_high_definition_sensitivity_v1/scripts/common.R')
source(file.path(root,'scripts/theme.R'));source(file.path(root,'scripts/export.R'));jin_setup()
initial_only<-'--initial'%in%commandArgs(TRUE);only_dataset<-'--only-dataset-direction'%in%commandArgs(TRUE);only_pathway<-'--only-pathways'%in%commandArgs(TRUE)
figs<-list();palette<-c(H50='#fdae61',H10='#f46d43',H05='#d73027');qpal<-c(Q50='#4575b4',Q90='#f46d43',Q95='#d73027');dict<-fread(tb('final_label_dictionary.tsv'));tmes<-dict[parent!='Epithelial',celltype]
export<-function(p,d,stem,w,h,info=''){
 if(only_dataset && !startsWith(stem,'dataset_direction_'))return(invisible(NULL))
 if(only_pathway && !startsWith(stem,'pathway_'))return(invisible(NULL))
 datafile<-file.path(root,'plot_data',paste0(stem,'.tsv.gz'));fwrite(d,datafile,sep='\t',na='NA',compress='gzip');p<-p+jin_theme();if(startsWith(stem,'dataset_direction_'))p<-p+theme(axis.text.x=element_text(angle=90,hjust=1,vjust=.5));f<-jin_export(p,file.path(root,'figures',stem),width=w,height=h);figs[[stem]]<<-data.table(figure_id=stem,file=unname(f),part=names(f),data_file=datafile,width_in=w,height_in=h,notes=info);cat('Rendered',stem,'\n')
}
d<-fread(tb('specimen_quantiles_coverage.tsv'));ec<-fread(tb('specimen_ecdf.tsv.gz'));ec<-merge(ec,d[,.(sample_uid,specimen_id,n_epi,zero_fraction,Q50,Q90,Q95)],by='sample_uid');ec[,sample_label:=paste0(specimen_id,' (n=',n_epi,')')];xlim<-range(ec$score)
for(ds in unique(ec$dataset)){
 v<-ec[dataset==ds];q<-unique(v[,.(sample_label,Q50,Q90,Q95)]);q<-melt(q,id.vars='sample_label',variable.name='quantile',value.name='score');p<-ggplot(v,aes(score,cdf))+geom_line(linewidth=.4)+geom_point(data=v[score==0],size=1.7)+geom_vline(data=q,aes(xintercept=score,colour=quantile),linewidth=.4)+scale_colour_manual(values=qpal,name=NULL)+facet_wrap(~sample_label,ncol=2)+scale_x_continuous(limits=xlim)+scale_y_continuous(limits=c(0,1))+labs(x='MP10 score',y='Cumulative Epi fraction');export(p,v,paste0('distribution_',ds),11,ceiling(uniqueN(v$sample_uid)/2)*2.6+1,'ECDF includes mass at zero; quantiles frozen from all original Epi; same score axis')
}
v<-fread(tb('dataset_equal_specimen_ecdf.tsv'));dp<-setNames(c('#377eb8','#e15759','#59a14f','#984ea3','#e6ab02'),sort(unique(v$dataset)));p<-ggplot(v,aes(score,cdf,colour=dataset))+geom_line(linewidth=.65)+scale_colour_manual(values=dp,name=NULL)+labs(x='MP10 score',y='Mean specimen ECDF')+scale_x_continuous(limits=xlim);export(p,v,'distribution_dataset_equal_specimen',8,5,'Each specimen contributes one ECDF equally; not pooled by cell count')
v<-melt(d,id.vars=c('sample_uid','dataset','specimen_id'),measure.vars=c('n_H50','n_H10','n_H05','k_s'),variable.name='quantity',value.name='cells');v[,specimen_id:=factor(specimen_id,levels=rev(d$specimen_id))];p<-ggplot(v,aes(cells,specimen_id,colour=quantity))+geom_point(size=2)+scale_x_log10()+labs(x='Cells (log scale)',y=NULL);
p<-p+scale_colour_manual(values=c(n_H50='#fdae61',n_H10='#f46d43',n_H05='#d73027',k_s='#000000'),name=NULL);export(p,v,'specimen_high_counts_sampling',8,13)
v<-melt(d,id.vars=c('sample_uid','dataset','specimen_id'),measure.vars=c('C10','C30'),variable.name='cohort',value.name='included');v[,specimen_id:=factor(specimen_id,levels=rev(d$specimen_id))];p<-ggplot(v,aes(cohort,specimen_id,fill=included))+geom_tile(colour='white',linewidth=.4)+scale_fill_manual(values=c('TRUE'='#4575b4','FALSE'='#e5e5e5'),name='Included')+labs(x=NULL,y=NULL);export(p,v,'specimen_cohort_coverage',6,13)
if(!initial_only){
 ef<-fread(tb('native_effects_rankings.tsv.gz'));ef[,high:=factor(high,levels=c('H50','H10','H05'))];ef[,target:=factor(target,levels=rev(tmes))];limit<-1.5
 heat<-function(v,stem,w=10,h=10){
 v<-copy(v);v[,label:=fcase(!computed | !target_in_background_universe,'NE',RR_status=='undefined_target_L_zero','L0',RR_status%in%c('undefined_background_L_zero','undefined_background_H_zero'),'B0',RR_status=='undefined_no_background','NB',!is.na(RR)&RR==0,'0',default='')];v[,plot_value:=ifelse(!is.na(RR)&RR==0,-limit,log2_RR)];v[,metric:=factor(metric,levels=c('W','R'),labels=c('Supported W','Raw R'))]
 p<-ggplot(v,aes(high,target,fill=plot_value))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=label),size=3.2)+scale_fill_gradient2(low='#2166ac',mid='white',high='#b2182b',midpoint=0,limits=c(-limit,limit),oob=scales::squish,na.value='#d9d9d9',name='log2(RR)',breaks=c(-1.5,-.75,0,.75,1.5),guide=guide_colourbar(display='rectangles'))+facet_grid(.~metric)+labs(x=paste0('High definition\n',v$cohort[1],' / ',v$scope[1],' / ',v$direction[1],' / min',v$min_cells[1]),y=NULL);export(p,v,stem,w,h,'Shared log2(RR) scale [-1.5,1.5] covers all finite effects in this run. 0=RR zero; NE=not evaluable; L0=target Low zero; B0=background denominator/ratio zero; NB=no background')
 }
 for(co in c('C10','C30'))for(di in c('output','input'))heat(ef[cohort==co & scope=='ALL' & direction==di & min_cells==10 & lr_domain=='fixed_full'],paste0(co,'_ALL_',di,'_effects'))
 for(ds in setdiff(unique(ef$scope),'ALL'))for(di in c('output','input'))heat(ef[cohort=='C10' & scope==ds & direction==di & min_cells==10 & lr_domain=='fixed_full'],paste0('C10_',ds,'_',di,'_effects'))
 # Same-input postfilter comparison, both thresholds on the explicit intersection background.
 cm<-fread(tb('comparable_background_effects.tsv.gz'));cm[,high:=factor(high,levels=c('H50','H10','H05'))];cm[,target:=factor(target,levels=rev(tmes))]
 for(di in c('output','input'))for(th in c(10,30))heat(cm[cohort=='C10' & scope=='ALL' & min_cells==th & comparison_context=='min10_min30_common' & direction==di & lr_domain=='fixed_full'],paste0('C10_ALL_',di,'_commonBG_min',th))
 for(di in c('output','input'))for(co in c('C10','C30'))heat(cm[cohort==co & scope=='ALL' & min_cells==10 & comparison_context=='C10_C30_common' & direction==di & lr_domain=='fixed_full'],paste0(co,'_ALL_',di,'_cohort_commonBG'))
 focus<-fread(tb('focus_candidate_union.tsv'))$target;cols<-setNames(dict$color,dict$celltype)
 for(di in c('output','input')){v<-ef[cohort=='C10' & scope=='ALL' & min_cells==10 & lr_domain=='fixed_full' & metric=='W' & direction==di & as.character(target)%in%focus];p<-ggplot(v,aes(high,rank_W_or_R,group=target,colour=target))+geom_line(linewidth=.4,na.rm=TRUE)+geom_point(size=2,na.rm=TRUE)+scale_y_reverse(breaks=seq(1,29,2))+scale_colour_manual(values=cols,name=NULL)+labs(x=paste0('High definition (C10 ALL, ',di,')'),y='Background-adjusted W rank');export(p,v,paste0('candidate_rank_',di),10,7,'Ranks cover all evaluable TME targets; displayed union includes predeclared six and ALL positive top3; RR<=1 is not enhancement')}
 sel<-fread(tb('focus_pathway_selection.tsv'));pa<-fread(tb('pathway_background_contributions.tsv.gz'));v<-merge(pa[cohort=='C10' & scope=='ALL' & min_cells==10 & lr_domain=='fixed_full' & grepl('(^|\\|)native(\\||$)',background_contexts)],sel[,.(target,direction,pathway)],by=c('target','direction','pathway'));v[,high:=factor(high,levels=c('H50','H10','H05'))]
 for(t in unique(v$target))for(di in unique(v[target==t,direction])){a<-v[target==t & direction==di];ord<-sel[target==t & direction==di,pathway];a[,pathway:=factor(pathway,levels=rev(ord))];a[,overall_state:=ifelse(!is.na(RR)&RR>1,'Overall RR > 1','Overall RR <= 1 or undefined')];a[,display_metric:=paste0(t,' (',di,')\n',metric,' (overall RR: ',paste(paste0(levels(high),'=',paste0(formatC(RR[match(levels(high),high)],digits=3,format='f'),ifelse(is.na(RR[match(levels(high),high)]),' (undefined)',ifelse(RR[match(levels(high),high)]<=1,' (<=1)','')))),collapse=', '),')'),by=metric];p<-ggplot(a,aes(E_path,pathway,fill=high))+geom_vline(xintercept=0,linewidth=.4,colour='#777777')+geom_col(position=position_dodge(width=.8),width=.7)+facet_wrap(~display_metric,ncol=1)+scale_fill_manual(values=palette,name='High definition')+labs(x='Pathway contribution to background-adjusted E',y=NULL);export(p,a,paste0('pathway_',gsub('[^A-Za-z0-9]','_',t),'_',di),10,7,'Top up to 5 positive E_path chosen on C10 ALL H05 W, fixed across H50/H10/H05; W and R; overall state explicitly labeled')}
 # Dataset direction and evaluability, with ALL comparison recomputed on each dataset's same background.
 for(di in c('output','input')){v<-cm[cohort=='C10' & min_cells==10 & lr_domain=='fixed_full' & direction==di & metric=='W' & grepl('^ALL_dataset_common:',comparison_context)];v[,dataset_comparison:=sub('ALL_dataset_common:','',comparison_context)];v[,column:=factor(paste(ifelse(scope=='ALL','ALL','Dataset'),high,sep='\n'),levels=as.vector(outer(c('ALL','Dataset'),c('H50','H10','H05'),paste,sep='\n')))];v[,state:=fcase(!computed | !target_in_background_universe,'NE',is.na(RR),'Undefined',RR>1,'RR > 1',RR==1,'RR = 1',default='RR < 1')];p<-ggplot(v,aes(column,target,fill=state))+facet_grid(.~dataset_comparison)+geom_tile(colour='white',linewidth=.4)+scale_fill_manual(values=c('NE'='#eeeeee','Undefined'='#777777','RR > 1'='#b2182b','RR = 1'='white','RR < 1'='#2166ac'),name=NULL)+labs(x=paste0('C10 / ',di,' / min10'),y=NULL)+theme(axis.text.x=element_text(angle=90,hjust=1));# export applies theme first so retain rotation below through custom export support
 p<-p+theme(axis.text.x=element_text(angle=90,hjust=1));export(p,v,paste0('dataset_direction_',di),18,12,'Each dataset is compared with ALL on its shared evaluable background; finite RR signs, not independent replication tests')}
 v<-fread(tb('node_counts.tsv'))[high=='H50' & node%in%tmes];v[,node:=factor(node,levels=rev(tmes))];v[,column:=paste(cohort,scope,sep='\n')];v[,coverage:=fcase(N<=10,'N <= 10 (NE)',N<=30,'10 < N <= 30',default='N > 30')];p<-ggplot(v,aes(column,node,fill=coverage))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=N),size=3)+scale_fill_manual(values=c('N <= 10 (NE)'='#eeeeee','10 < N <= 30'='#fdae61','N > 30'='#4575b4'),name=NULL)+labs(x=NULL,y=NULL);export(p,v,'dataset_node_coverage',13,11)
}
man<-rbindlist(figs);old<-file.path(root,'config/figure_manifest.tsv');if((initial_only||only_dataset||only_pathway) && file.exists(old)){prev<-fread(old);man<-rbindlist(list(prev[!figure_id%in%man$figure_id],man),fill=TRUE)};fwrite(man,old,sep='\t');write_json(list(font='Arial',size_pt=12,dpi=300,line_mm=.4,high_colors=palette,quantile_colors=qpal,heatmap_log2_RR_limits=c(-1.5,1.5),saturated_endpoints=FALSE,NE_colour='#d9d9d9',no_pseudocount=TRUE),file.path(root,'config/plot_config.json'),pretty=TRUE,auto_unbox=TRUE);cat('PLOTTING DONE\n')
